<span class="line"><span style="color:#ABB2BF;">  jint ergo_result </span><span style="color:#C678DD;">=</span><span style="color:#ABB2BF;"> Arguments::</span><span style="color:#61AFEF;">apply_ergo</span><span style="color:#ABB2BF;">();</span></span>
