<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> (Symbol</span><span style="color:#C678DD;">*</span><span style="color:#ABB2BF;">)(_ptr </span><span style="color:#56B6C2;">&amp;</span><span style="color:#56B6C2;"> ~</span><span style="color:#D19A66;">1</span><span style="color:#ABB2BF;">);</span></span>
